const pools={economy:throughDemand*clamp(1+(cs.economyComfort-m.comfort)/140,.7,1.2),business:throughDemand*clamp(.055+km/90000,.055,.15)*(.75+services(s)*.025),first:throughDemand*clamp(km/300000,.006,.045)*(.45+services(s)*.035)};
