 const seats=c[key]*legs,count=operating?Math.floor(Math.min(seats*.98,pools[key])):0,ticket=Math.round(fare*multiplier),income=count*(ticket+55)/1e6;
 classes[key]={seats,pax:count,fare:ticket,revenue:income,load:seats?count/seats:0};pax+=count;revenue+=income;handling+=count*(35+s.service.meal*13+s.service.cabin*8+extra)/1e6;experience+=count*comfort;
