function autoPricing(s){if(!s.autoPricing)return [];const changes=[];for(const r of s.routes.filter(r=>r.active&&s.fleet.some(p=>p.id===r.plane&&planeAvailable(s,p)))){const current=estimateLocal(s,r),best=[.65,.75,.85,1,1.15,1.3,1.5,1.8].map(price=>({price,profit:estimateLocal(s,{...r,price}).profit})).sort((a,b)=>b.profit-a.profit)[0];if(best.price!==r.price&&best.profit>current.profit+.01){changes.push({route:r.id,from:r.price,to:best.price});r.price=best.price;r.last=null;}}return changes;}
function hubInfluence(s){const value=Math.min(100,Math.max(0,s.baseInfluence||0)),index=ap(s.base).demand*(1+value*.0015),rank=D.airports.filter(a=>a.region==='CN'&&a.code!==s.base&&a.demand>index).length+1;return {value,index,rank};}
function growBase(s,points){if(!points)return;const before=hubInfluence(s);s.baseInfluence=Math.min(100,before.value+points);const after=hubInfluence(s);if(after.rank<before.rank){const crossed=D.airports.filter(a=>a.region==='CN'&&a.code!==s.base&&a.demand>before.index&&a.demand<=after.index).sort((a,b)=>b.demand-a.demand);addCompanyNews(s,{key:'city-'+s.base+'-'+after.rank,type:'city',title:ap(s.base).city+'的门户影响力提升',text:`游戏中的国内门户需求指数升至第 ${after.rank} 位，超过${crossed.slice(0,3).map(a=>a.city).join('、')}${crossed.length>3?'等城市':''}。`,detail:'城市合作积累的影响力持续提升基地相关航线需求，仍受座位、票价与竞争限制；这是游戏内指标。'});}}
