function score(s){return rankingMetrics(s).find(r=>r.player).score;}
function rankings(s){return rankingMetrics(s).sort((a,b)=>b.score-a.score||a.code.localeCompare(b.code));}
function addCompanyNews(s,item){if((s.companyNews||[]).some(n=>n.key===item.key))return;(s.companyNews||=[]).push({...item,week:s.week,priority:98});log(s,item.title+'：'+item.text,'good');}
function rankCrossings(s,before){const after=rankings(s),pos=after.findIndex(r=>r.player),old=before.findIndex(r=>r.player),passed=before.slice(0,old).filter(r=>after.findIndex(x=>x.code===r.code)>pos&&!(s.rankPassed||[]).includes(r.code));if(!passed.length)return;(s.rankPassed||=[]).push(...passed.map(r=>r.code));addCompanyNews(s,{key:'rank-'+s.week+'-'+passed.map(r=>r.code).join('-'),type:'milestone',title:'你超越了 '+passed.map(r=>r.name).join('、'),text:`全球综合排名由第 ${old+1} 位升至第 ${pos+1} 位。`,detail:'按机队规模、覆盖机场、航线密度、服务、口碑、可靠性和持续盈利综合比较；可在排行榜查看。'});}
