function log(s,text,type='info'){s.log.unshift({week:s.week,text,type});s.log=s.log.slice(0,150);}
const LESSORS=[{id:'northstar',name:'北辰航空租赁',factor:1,risk:.001,notice:4,term:104},{id:'skybridge',name:'天桥机队租赁',factor:.94,risk:.003,notice:2,term:52},{id:'horizon',name:'远航资产租赁',factor:1.07,risk:.0004,notice:6,term:156}];
function lessor(id){return LESSORS.find(l=>l.id===id)||LESSORS[0];}
function leaseInfo(p,s){return p.leaseContract||{lessor:'northstar',depositPaid:model(p.model).deposit,startWeek:s.week,term:104};}
function weeklyLease(p){return model(p.model).lease*lessor(p.leaseContract?.lessor).factor;}
function scheduleLeaseRecall(s,p,day=3,reason='出租方调整资产配置'){if(!p||p.mode!=='lease')throw Error('请选择租赁飞机。');const c=p.leaseContract||(p.leaseContract=leaseInfo(p,s));if(c.recall)return c.recall;const l=lessor(c.lessor);c.recall={dueWeek:s.week+l.notice,day:Math.max(0,Math.min(6,Math.floor(day))),reason,announcedWeek:s.week};const n={id:`lease-${p.id}-${s.week}`,week:s.week,kind:'notice',plane:p.id,model:p.model,lessor:l.name,...c.recall};(s.leaseNotices||=[]).unshift(n);s.leaseNotices=s.leaseNotices.slice(0,20);log(s,`${l.name}通知：${modelName(p.model)} 将于第 ${c.recall.dueWeek} 周周${'一二三四五六日'[c.recall.day]}收回。未使用租金按日退回，押金全额返还。`,'warn');return c.recall;}
function prepareLeases(s){for(const p of s.fleet.filter(p=>p.mode==='lease')){const c=p.leaseContract||(p.leaseContract=leaseInfo(p,s)),l=lessor(c.lessor);if(p.delivery||c.recall)continue;if(s.week>=c.startWeek+c.term-l.notice){scheduleLeaseRecall(s,p,0,'租赁期限届满');}else if(s.week-c.startWeek>=13&&rand(s)<l.risk)scheduleLeaseRecall(s,p,1+Math.floor(rand(s)*6));}return s.fleet.filter(p=>p.mode==='lease'&&!p.delivery&&p.leaseContract.recall&&p.leaseContract.recall.dueWeek<=s.week).map(p=>({plane:p.id,model:p.model,lessor:lessor(p.leaseContract.lessor).name,day:p.leaseContract.recall.dueWeek<s.week?0:p.leaseContract.recall.day,deposit:p.leaseContract.depositPaid}));}
