function pay(s,v){if(!Number.isFinite(v)||v<0||s.cash<v)throw Error('可用现金不足，请调整计划或申请融资。');s.cash-=v;}
function validateRoute(s,r,exclude){if(!ap(r.from)||!ap(r.to)||r.from===r.to)throw Error('请选择两个不同的机场。');if(!s.hubs.some(h=>h.code===r.from))throw Error('出发机场必须是你的运营基地。');if(s.routes.some(x=>x.id!==exclude&&([x.from,x.to].sort().join() === [r.from,r.to].sort().join())))throw Error('这条航线已在航网中，请调整现有航班。');let p=s.fleet.find(x=>x.id===r.plane);if(!p||!planeAvailable(s,p))throw Error('请选择已经交付、可执行航班的飞机。');if(!Number.isInteger(r.freq)||r.freq<1||r.freq>28)throw Error('每周往返班次必须在 1–28 之间。');if(!Number.isFinite(r.price)||r.price<.65||r.price>1.8)throw Error('票价系数必须在 65%–180% 之间。');if(r.via&&(!ap(r.via)||r.via===r.from||r.via===r.to))throw Error('经停机场须与始发、终点不同。');if(r.via&&(!Number.isInteger(stopMinutes(r))||stopMinutes(r)<60||stopMinutes(r)>720))throw Error('经停时间至少 60 分钟，最多 720 分钟。');if(routeInternational(r)&&!s.license)throw Error('请先在「公司发展」申请国际及地区航线资质。');if(routeLegs(r).some(l=>l.km>model(p.model).range*.94))throw Error('航程超过该机型的游戏运营限制（预留 6% 余量）。');if(usedHours(s,p.id,exclude)+routeHours(r)*2*r.freq>100)throw Error('飞机每周可排班 100 小时，请减班或改派另一架飞机。');const hub=s.hubs.find(x=>x.code===r.from);if(s.routes.filter(x=>x.from===r.from&&x.active&&x.id!==exclude).reduce((a,x)=>a+x.freq*2,0)+r.freq*2>hub.level*180)throw Error('基地时刻已满，请先扩建基地。');schedulePlan({...s,routes:[...s.routes.filter(x=>x.id!==exclude),{...r,id:exclude??-1}]},p.id);}
function aircraftAvailable(s,m){m=typeof m==='string'?model(m):m;return !!m&&(!m.fictional||Number(s.date.slice(0,4))>=m.releaseYear);}
